const strikeThrough = { textDecoration: "line-through" };
var isDone = false;

function App() {
  return <p style={isDone ? strikeThrough : null}>Buy milk</p>;
}

export default App;

// <button onclick="strike()">Strike</button>  <button onclick="unStrike()">Undo</button>
function strike() {
  document.getElementById("root").style.textDecoration = "line-through";
}

function unStrike() {
  document.getElementById("root").style.textDecoration = null; // clears the inline style
}

var isDone = false;
function strike() { isDone = true; }
function unStrike() { isDone = false; }

function App() {
  return (
    <div>
      <p style={isDone ? { textDecoration: "line-through" } : null}>Buy milk</p>
      <button onClick={strike}>Change to strike through</button>
      <button onClick={unStrike}>Change back</button>
    </div>
  );
}
